import React, { useState } from 'react';
import Result from './Result';


 export default function Close(){
    let [flag,setflag]=useState(true)
    function handleclick(){
        console.log('working')
        setflag(!flag)
    }
    return(
        <>
        <button onClick={handleclick}>{flag?'close':"false"}</button>
        {flag &&<Result/>}
        
        </>
    )
}
